'use client';

import { useState } from 'react';

import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { AgentRow } from './agent-row';
import { type AgentId, type Change, HERO, INITIAL_CHANGE } from './data';
import { WordPill } from './word-pill';

/** The demonstration walks the agents in this order and ends on the one the hero began with. */
const DEMO_ORDER: AgentId[] = [
  'researcher',
  'writer',
  'reviewer',
  'coder',
  'planner',
];

const PICK_EVERY_MS = 2600;

function changedTo(current: Change, agent: AgentId): Change {
  if (current.to === agent) {
    return current;
  }
  return { id: current.id + 1, from: current.to, to: agent };
}

export default function Heroes09() {
  const [change, setChange] = useState<Change>(INITIAL_CHANGE);
  const { pressed, press } = usePress<AgentId>();

  function pick(agent: AgentId) {
    setChange((current) => changedTo(current, agent));
  }

  function startOver() {
    setChange(INITIAL_CHANGE);
  }

  const steps: AutoplayStep[] = DEMO_ORDER.flatMap((agent) => [
    { after: PICK_EVERY_MS, run: () => press(agent) },
    { after: PRESS_LEAD_MS, run: () => pick(agent) },
  ]);
  const { ref } = useAutoplay(steps, { loopAfter: 0, onReset: startOver });

  return (
    <section className='@container'>
      <div
        ref={ref}
        className='mx-auto flex max-w-4xl flex-col items-center gap-8 px-4 py-16 text-center @2xl:gap-10 @2xl:px-6 @2xl:py-24'
      >
        <AgentRow lit={change.to} pressed={pressed} onPick={pick} />
        <h1 className='text-4xl leading-[1.15] font-semibold text-balance @2xl:text-5xl @4xl:text-6xl'>
          {HERO.titleStart}{' '}
          <span className='mt-1 block'>
            <WordPill change={change} />
          </span>
        </h1>
        <p className='text-muted-foreground max-w-xl text-base text-pretty'>
          {HERO.description}
        </p>
        <div className='flex flex-wrap justify-center gap-2'>
          <Button size='lg' nativeButton={false} render={<a href='#' />}>
            {HERO.primaryAction}
            <ArrowRightIcon />
          </Button>
          <Button
            size='lg'
            variant='outline'
            nativeButton={false}
            render={<a href='#' />}
          >
            {HERO.secondaryAction}
          </Button>
        </div>
      </div>
    </section>
  );
}

'use client';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { AGENTS, type AgentId, HERO } from './data';

const LIT_CARD =
  'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.06]';

const AGENT_ITEM = 'bg-foreground/[0.04] h-9 rounded-full ps-1 pe-3';

function isAgentId(value: unknown): value is AgentId {
  return AGENTS.some((agent) => agent.id === value);
}

type AgentRowProps = {
  lit: AgentId;
  pressed: AgentId | null;
  onPick: (agent: AgentId) => void;
};

export function AgentRow({ lit, pressed, onPick }: AgentRowProps) {
  const litValues = [lit];

  /** Pressing the lit agent again keeps it: the headline always has a word. */
  function change(values: unknown[]) {
    const [next] = values;
    if (isAgentId(next)) {
      onPick(next);
    }
  }

  return (
    <ToggleGroup
      aria-label={HERO.agentsLabel}
      value={litValues}
      onValueChange={change}
      travel
      indicatorClassName={LIT_CARD}
      className='flex w-full flex-wrap justify-center gap-1.5'
    >
      {AGENTS.map((agent) => (
        <ToggleGroupItem
          key={agent.id}
          value={agent.id}
          className={cn(AGENT_ITEM, pressedQuietOf(pressed === agent.id))}
        >
          <MeshTile
            seed={agent.role}
            color={seriesColorOf(agent.series)}
            size='lg'
          />
          {agent.role}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

import type { CSSProperties } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { cn } from '@/registry/ndeko/lib/utils';

import { AGENTS, type AgentId, type Change } from './data';

type ChipStyle = CSSProperties & { '--chip': string };

function agentOf(id: AgentId) {
  const found = AGENTS.find((agent) => agent.id === id);
  return found ?? AGENTS[0];
}

function chipStyleOf(id: AgentId) {
  const agent = agentOf(id);
  const style: ChipStyle = { '--chip': seriesColorOf(agent.series) };
  return style;
}

/** The first colour is there from the start; only a colour that replaces another sweeps in. */
function wipeClassOf(hasChanged: boolean) {
  if (hasChanged) {
    return 'starting:scale-x-0';
  }
  return undefined;
}

const LAYER = 'chip-3d absolute inset-0 -z-10 rounded-[inherit]';

const WIPE_LAYER =
  'origin-left transition-transform duration-500 ease-(--ease-out-strong) motion-reduce:transition-none';

type WordPillProps = {
  change: Change;
};

/**
 * The word of the headline in a pill. A new word rolls in while the colour of its agent sweeps
 * over the old one from the left: the new layer is mounted again for each change, and it starts
 * with no width.
 */
export function WordPill({ change }: WordPillProps) {
  const agent = agentOf(change.to);
  const hasChanged = change.id > 0;

  return (
    <span className='relative isolate inline-flex overflow-hidden rounded-2xl px-3 py-0.5 @2xl:px-4'>
      <span
        key={`from-${change.id}`}
        aria-hidden='true'
        style={chipStyleOf(change.from)}
        className={LAYER}
      />
      <span
        key={`to-${change.id}`}
        aria-hidden='true'
        style={chipStyleOf(change.to)}
        className={cn(LAYER, WIPE_LAYER, wipeClassOf(hasChanged))}
      />
      <WordRoll text={agent.role} />
    </span>
  );
}

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';

export type AgentId =
  'planner' | 'researcher' | 'writer' | 'reviewer' | 'coder';

export type Agent = {
  id: AgentId;
  role: string;
  series: SeriesSlot;
};

/** The word of the headline changes from one agent to another; the id counts the changes. */
export type Change = {
  id: number;
  from: AgentId;
  to: AgentId;
};

export const HERO = {
  titleStart: 'Hand the next task to your',
  description:
    'Each agent owns one kind of work and shows its steps as it goes. You read what it made before anything leaves your workspace.',
  primaryAction: 'Meet the agents',
  secondaryAction: 'See a run step by step',
  agentsLabel: 'Agents',
};

export const AGENTS: Agent[] = [
  { id: 'planner', role: 'Planner', series: 1 },
  { id: 'researcher', role: 'Researcher', series: 2 },
  { id: 'writer', role: 'Writer', series: 3 },
  { id: 'reviewer', role: 'Reviewer', series: 4 },
  { id: 'coder', role: 'Coder', series: 5 },
];

export const FIRST_AGENT: AgentId = 'planner';

export const INITIAL_CHANGE: Change = {
  id: 0,
  from: FIRST_AGENT,
  to: FIRST_AGENT,
};
